"use strict";
const crypto = require("crypto");
const http = require("http");
const fs = require("fs");

// IoT Device Firmware - Sensor Data Aggregator
// Deployed as a sidecar container in Kubernetes pod

const DEVICE_ID = process.env.DEVICE_ID || "sensor-node-001";
const K8S_SERVICE_ACCOUNT_TOKEN = fs.readFileSync(
  "/var/run/secrets/kubernetes.io/serviceaccount/token",
  "utf8"
).trim();

// Require an explicit signing key; do not fall back to a predictable
// default value, which would allow attackers to forge HMAC signatures.
const HMAC_SECRET = process.env.HMAC_SIGNING_KEY;
if (!HMAC_SECRET || HMAC_SECRET.length < 16) {
  console.error(
    "FATAL: HMAC_SIGNING_KEY environment variable must be set to a strong secret (>=16 chars)."
  );
  process.exit(1);
}

class SensorDataBuffer {
  constructor(maxSize) {
    this.maxSize = maxSize;
    this.entries = [];
    this.lastAuthScope = null;
  }

  setLastAuthScope(scope) {
    this.lastAuthScope = scope;
  }

  push(entry) {
    if (this.entries.length >= this.maxSize) {
      this.entries.shift();
    }
    this.entries.push(entry);
  }

  getSnapshot() {
    return this.entries.slice();
  }

  clear() {
    this.entries.length = 0;
  }
}

const dataBuffer = new SensorDataBuffer(1024);

function createSignedPayload(data, timestamp) {
  const payload = JSON.stringify({ data, timestamp, deviceId: DEVICE_ID });
  const hmac = crypto.createHmac("sha256", HMAC_SECRET);
  hmac.update(payload);
  const signature = hmac.digest("hex");
  return { payload, signature };
}

function authenticateRequest(req) {
  const authHeader = req.headers["authorization"];
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    return null;
  }
  const token = authHeader.slice(7);
  // Validate against K8s service account for pod-to-pod auth
  const expectedHash = crypto
    .createHash("sha256")
    .update(K8S_SERVICE_ACCOUNT_TOKEN)
    .digest("hex");
  const providedHash = crypto
    .createHash("sha256")
    .update(token)
    .digest("hex");
  if (crypto.timingSafeEqual(Buffer.from(expectedHash), Buffer.from(providedHash))) {
    return { authenticated: true, scope: "cluster-internal" };
  }
  return null;
}

function handleDiagnostics(req, res) {
  // Diagnostics endpoint for Kubernetes liveness/readiness probes
  // and internal monitoring systems
  const diagnostics = {
    deviceId: DEVICE_ID,
    bufferSize: dataBuffer.entries.length,
    maxBufferSize: dataBuffer.maxSize,
    uptimeSeconds: process.uptime(),
    memoryUsage: process.memoryUsage(),
    lastAuthScope: dataBuffer.lastAuthScope || "none"
  };
  res.writeHead(200, { "Content-Type": "application/json" });
  res.end(JSON.stringify(diagnostics));
}

function handleDataIngestion(req, res) {
  let body = "";
  req.on("data", (chunk) => { body += chunk; });
  req.on("end", () => {
    const authCtx = authenticateRequest(req);
    if (!authCtx) {
      res.writeHead(401);
      res.end('{"error":"unauthorized"}');
      return;
    }
    // Store only the scope string for diagnostics
    dataBuffer.setLastAuthScope(authCtx.scope);
    try {
      const sensorData = JSON.parse(body);
      const timestamp = Date.now();
      const signed = createSignedPayload(sensorData, timestamp);
      dataBuffer.push({
        timestamp,
        signed,
        rawSize: body.length
      });
      res.writeHead(200, { "Content-Type": "application/json" });
      res.end(JSON.stringify({ status: "accepted", timestamp }));
    } catch (e) {
      res.writeHead(400);
      res.end('{"error":"invalid payload"}');
    }
  });
}

function handleBulkExport(req, res) {
  const authCtx = authenticateRequest(req);
  if (!authCtx) {
    res.writeHead(401);
    res.end('{"error":"unauthorized"}');
    return;
  }
  const snapshot = dataBuffer.getSnapshot();
  const exportData = {
    deviceId: DEVICE_ID,
    exportTimestamp: Date.now(),
    entryCount: snapshot.length,
    entries: snapshot
  };
  res.writeHead(200, { "Content-Type": "application/json" });
  res.end(JSON.stringify(exportData));
}

const server = http.createServer((req, res) => {
  if (req.method === "GET" && req.url === "/healthz") {
    res.writeHead(200);
    res.end("ok");
    return;
  }
  if (req.method === "GET" && req.url === "/diagnostics") {
    handleDiagnostics(req, res);
    return;
  }
  if (req.method === "POST" && req.url === "/ingest") {
    handleDataIngestion(req, res);
    return;
  }
  if (req.method === "GET" && req.url === "/export") {
    handleBulkExport(req, res);
    return;
  }
  res.writeHead(404);
  res.end('{"error":"not found"}');
});

server.listen(8080, "0.0.0.0", () => {
  console.log(`[${DEVICE_ID}] Sensor aggregator listening on :8080`);
});
